/* From Uiverse.io by Admin12121 - Tags: animated, card animation, card hover, 3d card */
.__UIV_SCOPE__ .product-container {
  position: relative;
}

.__UIV_SCOPE__ .card {
  font-family: Lato, sans-serif;
  position: relative;
  width: 290px;
  height: 400px;
  background: #232323;
  border-radius: 20px;
  overflow: hidden;
}

.__UIV_SCOPE__ .card:before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--product-color);
  clip-path: circle(150px at 80% 20%);
  transition: .5s ease-in-out;
}

.__UIV_SCOPE__ .card:hover:before {
  clip-path: circle(300px at 80% -20%);
}

.__UIV_SCOPE__ .title {
  position: relative;
  font-weight: 600;
  letter-spacing: 1px;
  color: #fff;
  margin-top: 12px;
}

.__UIV_SCOPE__ .bg-title {
  font-size: 10em;
  font-weight: 900;
  font-style: italic;
  color: rgba(255,255,255,.04);
  position: absolute;
  max-width: 120%;
  top: -150%;
  transition: .6s;
}

.__UIV_SCOPE__ .card:hover .bg-title {
  transform: translateY(60%);
}

.__UIV_SCOPE__ .photo {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 100%;
  height: 220px;
  transition: .5s;
}

.__UIV_SCOPE__ .card:hover .photo {
  top: 0%;
  transform: translateY(0%);
}

.__UIV_SCOPE__ .photo img {
  position: absolute;
  width: 220px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-25deg);
  transition: .5s;
}

.__UIV_SCOPE__ .card:hover .photo img {
  width: 260px;
  top: 56%;
}

.__UIV_SCOPE__ .content {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 100px;
  text-align: center;
  transition: 1s;
  z-index: 5;
}

.__UIV_SCOPE__ .card:hover .content {
  height: 190px;
}

.__UIV_SCOPE__ .feature {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 8px 20px;
  transition: .5s;
  visibility: hidden;
  opacity: 0;
}

.__UIV_SCOPE__ .card:hover .feature {
  visibility: visible;
  opacity: 1;
  transition-delay: .5s;
}

.__UIV_SCOPE__ .feature div {
  color: #fff;
  font-weight: 300;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-right: 10px;
}

.__UIV_SCOPE__ .feature span {
  min-width: 20px;
  padding: 0 4px;
  height: 26px;
  text-align: center;
  line-height: 26px;
  font-size: 14px;
  display: inline-block;
  color: #111;
  background: #fff;
  margin: 0 5px;
  transition: .4s;
  border-radius: 4px;
  cursor: pointer
}

.__UIV_SCOPE__ .feature span:hover {
  color: #000;
  background: var(--product-color);
}

.__UIV_SCOPE__ .btn-buy {
  display: inline-block;
  padding: 10px 20px;
  background: #fff;
  border: none;
  border-radius: 4px;
  margin-top: 10px;
  text-decoration: none;
  font-weight: 600;
  color: #111;
  opacity: 0;
  transform: translateY(50px);
  transition: 0.5s;
  cursor: pointer;
  outline: none;
}

.__UIV_SCOPE__ .card:hover .btn-buy {
  opacity: 1;
  transform: translateY(0px);
  transition: 0.5s;
  transition-delay: 0.5s;
}

.__UIV_SCOPE__ .card:hover .btn-buy:hover {
  background: var(--product-color);
  transition-delay: 0;
  transition: 0.05s;
}

.__UIV_SCOPE__ .product-1 {
  --product-color: #EB6CA4;
}

.__UIV_SCOPE__ .size span {
  cursor: pointer;
  z-index: 50;
}

.__UIV_SCOPE__ .feature .tt:hover {
  background: #038dff;
}

.__UIV_SCOPE__ .feature .ttt:hover {
  background: #09ff0d;
}
